const H=\"D:/work/other/ai-writer/acceptance/20261019-hundred-h\",n=81,note=\"# 81章逐项实读复核\\n\\n保护会话内完整读当前81，承72范围付费与74/78相处。正文655c6247850732a67d16febccc2661709a509498be8bcef66fb4976c02614c7b不改。\\n\\n- summary：49早新12分换土样只试开，约50日9–11完整声画/定位480且实收预240未交；4元硬垫片反复减层稳桌，今日独处确实生活完成，周球场只有消息鞋照不见胜负。原摘要准确。\\n- characters：梁催单也有自己的等待压力，答具体十一点前可联而非恶意占周；沈不替重剪或逐字查字幕。周明知独处不只工作借口，知道新家中两小时活，没获价格文件。沈没赴球场，不能从跑热鞋照记已见进球。双方旧知情与各家选择保留。\\n- timeline：49收到/预付、50工作未执行、51午前定为梁目标不等沈承包后制。桌快11点稳、午饭/下午洗头/六点晚饭/19:40多照片及睡前收桌顺序明确；旧72结的480与本次新预240不混，4元不是冲抵成净收入。\\n- ledger：T_HOME_LISTEN_81 pending与P_HOME_NEW_AUDIO_81 active独立建项；文件独立夹、旧纸旧盘不动不垫桌。T_PAID_WORK仍保留72阶段resolved，但其中周的旧78“近期未接新单”不能继续当现在；新增81从沈口述已接明日在家两小时、金额文件未知的当前知识，旧78全文留作历史，不改原statement/type/author_truth。T_RETURN_MONTH partial，原一个月不当已满/同居。\\n- evidence：预240到账、今天本来想独处、桌腿稳、50九至十一、尾格空、蓝盆/新文件夹以及鞋照不见进球等锚均实在。T_PAID_WORK新增周81知识另加45行“她只告诉他本次在家做两小时”作为当章依据，保留原预付锚与历史证据。\\n- downstream：本批止81，82要实际执行新单才记结果，不提前写82–91或110–112的新知识。83扣盒/转述候选已改但尚未重登，107三留用与109昨天仍待后批summary核。旧154账本身份/初始观察、原纸盒钥私册及未知声音私人原因不改。\\n\\n六项经具体阅读复核。除本条派生知情及相应引文补充外保留原草案；本批不提前准备或提交，知情自检不冒充正式验收。\\n\";const fs=require('node:fs'),p=require('node:path');const D=p.join(H,'revise-a'),s=JSON.parse(fs.readFileSync(p.join(D,'session.json'))),r=JSON.parse(fs.readFileSync(p.join(H,'commands/revise-a-replay-'+n+'/stdout.raw.txt')));fs.writeFileSync(p.join(D,'semantic-'+n+'.md'),note,{flag:'wx'});const ref='审查/H-revise-a-replay-'+n+'.md';fs.copyFileSync(p.join(D,'semantic-'+n+'.md'),p.join(s.workspace,ref),fs.constants.COPYFILE_EXCL);const old=r.changes.ledger.T_PAID_WORK.character_known['周砚'];r.changes.ledger.T_PAID_WORK.character_known['周砚']='第81章：49消息从沈获已新接明日在镇家两小时核听及今天想独处；只见桌脚照，不知本次480/预240或客户文件。；历史有效信息（保留原章次，非当前状态）：'+old;r.changes.ledger.T_PAID_WORK.evidence.push({unit:81,quote:'她只告诉他本次在家做两小时'});;r.replay_review={reviewer:'Codex-H-revise-a-informed-self-review',report:ref,draft_sha256:r._replay.draft_sha256,checked_fields:['summary','characters','timeline','ledger','evidence','downstream']};fs.writeFileSync(p.join(D,'record-'+n+'.json'),JSON.stringify(r,null,2)+'\\n',{flag:'wx'});
'@ | node"

