const fs=require('node:fs'),p=require('node:path'),a=require('node:assert/strict');const H=\"D:/work/other/ai-writer/acceptance/20261019-hundred-h\",D=p.join(H,'revise-a'),s=JSON.parse(fs.readFileSync(p.join(D,'session.json'))),r=JSON.parse(fs.readFileSync(p.join(H,'commands/revise-a-review-template-67-81/stdout.raw.txt')));const rows=[[67,[\"把新核听问成有范围的工作，也保住晚饭安排\",\"先发我这次片子的编号、总长和要我给什么。\"],[\"梁想尽早交，改后范围与交期未定\",\"真今晚，我接不了。\"],[\"先让梁定交期，不因有文件就开工\",\"今天先别开工。\"],[\"一次480报价仍待正式确认，晚饭另已实约\",\"工作那一格仍留问号，饭这一格是两个人刚才真正约过的。\"],[\"沈周约一顿不被工作电话截断的饭\",\"想做一顿不用吃一半便回工作电话的饭。\"]],[68,[\"让已做勘看结束后仍能作为顾客来往\",\"以后来吃，别因为这次没成就一直不来。\"],[\"葛以为付钱能立即添码，沈也失落没后单\",\"后悔有一点。\"],[\"葛自己停码并正式告印人\",\"这次不做声音码，按茶食这张改\"],[\"旧料不印，本次新核听正式接并核收预240\",\"二百四十随后到了，她核收\"],[\"双方承认想成单，仍容一份点心的普通往来\",\"但不能为有活，叫你先把不需要的买完。\"]],[69,[\"完整核本次初剪并交可定位意见\",\"从第一秒完整看听下去\"],[\"顺剪把真实等照片动作切没，时长又受限\",\"我把等小图那句留着了。\"],[\"回原遍与选择号，以可复核小段试改\",\"手指、照片和下一步得在同一回动作里走通。\"],[\"15:46交意见获收，尾240仍未到\",\"十五点四十六，完整意见发给梁与陆。\"],[\"与温陆共同付调整成本而非越权替全片验收\",\"今天交的是意见。\"]],[70,[\"两个人实际共同做一顿饭\",\"两个人就得都慢点。\"],[\"厨房窄和蒸蛋老，使合拍不能靠口头夸\",\"咱俩先别比赛谁更抱歉。\"],[\"分别做手边活、承认不完美还愿一起吃\",\"老一点，但不是不能吃。\"],[\"兑现饭约并约44日谈月，非永久同住\",\"他们定第四十四日晚八点\"],[\"周要知道下月而沈认真答，不靠彼此默猜\",\"我也有我想去的地方。\"]],[71,[\"让邹本次宽车过雨堵，问后续谁经办\",\"那找谁讲？\"],[\"纸堵积泥与侧筐使伞宽估计无效\",\"你看的是你这一把伞。\"],[\"范托软纸收料而非往下游推，沈守布\",\"没顺水推到下一处。\"],[\"本次通过仍有下次责任缺口\",\"今天过了。下次我来，你们正好谁也不在呢？\"],[\"范答问经办，沈不代邹承诺到场\",\"自己在，可以先帮问，但不保经办那时已经肯来。\"]],[72,[\"何来做客、补全滑夹经过并结核听尾款\",\"想来坐半小时\"],[\"梁可能两条却想占一周，沈仍怕失单\",\"你真不怕我临时找了别人？\"],[\"保留首次告知后不验夹；拒未确认七个下午\",\"何说自己不跑去邱铺看夹得牢不牢。\"],[\"480实际收齐，未来工作另定范围\",\"这一次两小时核听共四百八十，真的齐了。\"],[\"何是朋友和介绍人，不为后单作保\",\"你介绍人，不是替我保一份一定成的活。\"]],[73,[\"实际找到材料经办并问可共看的时刻\",\"乔平，这边材料车进出先找他。\"],[\"错货与空框搬运让新增协调有工时成本\",\"谁都说你顺手办，我顺不过来。\"],[\"空框先落稳让人过，沈改问一次真实同看\",\"框底真正靠稳以后，范才让出门边。\"],[\"45日9:20实约成，车9:30仍可能迟\",\"九点二十可以先停几分钟。\"],[\"乔成为自己答应的接车人，邹仍自己决定时段\",\"她今天没答应来。\"]],[74,[\"兑现一小时谈月，作明确住处选择\",\"从现在往后这一个月，我住这里。\"],[\"沈把尚未说的晚饭当成被周球约占去\",\"我想过一遍，就像已经说给你听了。\"],[\"接受各自日子，讲清出差与同住边界\",\"她说现在各住各的\"],[\"47晚具体约成，未来月仍待过\",\"六点半看一会儿，七点半以